def before(case):
    items, coupon = case
    subtotal = sum(items)
    if coupon:
        subtotal = subtotal * 0.9
    tax = subtotal * 0.07
    return round(subtotal + tax, 2)

def subtotal_of(items):
    return sum(items)

def apply_coupon(subtotal, coupon):
    return subtotal * 0.9 if coupon else subtotal

def tax_on(amount):
    return amount * 0.07

def after(case):
    items, coupon = case
    discounted = apply_coupon(subtotal_of(items), coupon)
    return round(discounted + tax_on(discounted), 2)

