def before(case):
    fmt, rows = case
    class Base:
        def export(self, rs):
            return "\n".join(rs)
    class Csv(Base):
        def export(self, rs):
            return ",".join(rs)
    class Json(Base):
        def export(self, rs):
            return "[" + ",".join(rs) + "]"
    exporter = Csv() if fmt == "csv" else Json()
    return exporter.export(rows)

def csv_rows(rows):
    return ",".join(rows)

def json_rows(rows):
    return "[" + ",".join(rows) + "]"

FORMATTERS = {"csv": csv_rows, "json": json_rows}

def after(case):
    fmt, rows = case
    return FORMATTERS[fmt](rows)

