def before(case):
    lines, rate = case
    total = 0
    for line in lines:
        name, price = line.split(":")
        total += float(price) * (1 - rate)
    return round(total, 2)

def parse_items(lines):
    items = []
    for line in lines:
        name, price = line.split(":")
        items.append((name, float(price)))
    return items

def discounted_total(items, rate):
    return round(sum(price * (1 - rate) for name, price in items), 2)

def after(case):
    lines, rate = case
    return discounted_total(parse_items(lines), rate)

