def before(case):
    sums = {}
    counts = {}
    for cat, amount in case:
        if cat not in sums:
            sums[cat] = 0
            counts[cat] = 0
        sums[cat] += amount
        counts[cat] += 1
    return (sorted(sums.items()), sorted(counts.items()))

def accumulate(pairs, combine):
    out = {}
    for key, value in pairs:
        out[key] = combine(out.get(key, 0), value)
    return out

def after(case):
    sums = accumulate(case, lambda acc, v: acc + v)
    counts = accumulate([(cat, 1) for cat, amount in case], lambda acc, v: acc + v)
    return (sorted(sums.items()), sorted(counts.items()))

