def before(case):
    lines = []
    total = 0
    for name, pts in case:
        bonus = 5 if pts >= 50 else 0
        lines.append(name + ": " + str(pts + bonus))
        total += pts + bonus
    return (lines, total)

def bonus_for(pts):
    return 5 if pts >= 50 else 0

def player_line(name, pts):
    return name + ": " + str(pts + bonus_for(pts))

def after(case):
    lines = [player_line(name, pts) for name, pts in case]
    total = sum(pts + bonus_for(pts) for name, pts in case)
    return (lines, total)

