def before(case):
    a = case.lower().replace(" ", "-").replace(".", "")
    b = case.upper().replace(" ", "_").replace(".", "")
    return (a, b)

def slugify(text, lower=True, sep="-"):
    out = text.lower() if lower else text.upper()
    return out.replace(" ", sep).replace(".", "")

def after(case):
    return (slugify(case), slugify(case, lower=False, sep="_"))

